// GENERATED FAQ data (English source strings; Arabic via tr()). Offline, no user data.
class FaqEntry {
  final String id, q, a, kw;
  const FaqEntry(this.id, this.q, this.a, this.kw);
}

const List<FaqEntry> kFaq = [
  FaqEntry('quick', 'How do I log a case quickly?', 'Tap the + button and choose Quick case. Fill only the complaint and diagnosis, and finish the details later. Long-press the + button to open Quick case directly.', 'quick fast add new log case record + | سريع سريعة أضف حالة تسجيل جديدة'),
  FaqEntry('full', 'How do I write a full case?', 'Tap + then Full case. The case has tabs: Info, History, Exam, Investigations, Assessment, Management, Progress, Learning and Timeline. A green dot on a tab means it has content. Everything saves automatically.', 'full case tabs history exam write sections autosave save | كاملة تبويبات قصة فحص كتابة حفظ'),
  FaqEntry('autosave', 'Do I need to press Save?', 'No. The case saves automatically a moment after you type. The top bar shows Saved or Saving. Use the Undo arrow to go back a step.', 'save saved autosave undo lost | حفظ تلقائي تراجع فقدان'),
  FaqEntry('fill', 'What does Quick fill from template do?', 'In the case menu, Quick fill from specialty template adds a structured history and exam outline for the chosen specialty. Fill everything normal fills only empty fields and marks them as auto-filled so you confirm them. Vital signs and results are never filled.', 'template quick fill normal auto structure soap socrates | قالب ملء سريع طبيعي تلقائي'),
  FaqEntry('edit', 'How do I edit or delete a case?', 'Open the case from the Cases tab and edit any field. To delete, open the case menu (three dots) and choose Delete case.', 'edit delete remove change case | تعديل حذف إزالة تغيير حالة'),
  FaqEntry('search', 'How do I search my cases?', 'Use the search box in the Cases tab. You can type plain words or use filters such as #tag, dx:pneumonia, spec:, setting:, is:starred, has:image. Use a minus sign to exclude a word.', 'search find filter tag dx spec starred query | بحث ابحث تصفية وسم'),
  FaqEntry('tags', 'How do I use tags and stars?', 'In the Info tab of a case add tags, star the case, or mark it To review later. Then filter by them from the Cases tab.', 'tags tag star starred review later favourite | وسم وسوم نجمة مراجعة مفضلة'),
  FaqEntry('image', 'How do I add a photo to a case?', 'In the Investigations tab add an image from the camera or gallery. Cover any name before taking the photo. You can annotate, crop and hide areas inside the app. Photos are stored privately inside the app, not in your gallery.', 'photo image picture camera xray annotate cover gallery | صورة صور كاميرا أشعة تعليق'),
  FaqEntry('procedure', 'How do I log a procedure?', 'Tap + and choose Procedure. Pick the procedure, your role (observed, assisted, performed under supervision, performed independently) and your confidence. Counts feed your goals.', 'procedure procedures skill cannulation role confidence log | إجراء إجراءات مهارة دور'),
  FaqEntry('note', 'What are notes, questions, pearls and tasks?', 'The + menu also adds a Note, a clinical Question for later, a Pearl (one thing learned today, with a streak) and a Task with a due date.', 'note notes question pearl pearls task tasks todo streak | ملاحظة سؤال درة مهمة مهام'),
  FaqEntry('rotation', 'How do I set up a rotation?', 'Open Portfolio, then Rotations, and add a rotation with its name, hospital or department and start and end dates. New cases can then be linked to it, and you can export the rotation as PDF.', 'rotation rotations department block hospital start end | دورة دورات قسم مستشفى'),
  FaqEntry('goals', 'How do I set goals and targets?', 'In a rotation, add Targets: number of cases, a procedure with performed and assisted counts, notes, reflections or signed entries. Progress bars update as you log.', 'goals goal target targets progress requirement count | أهداف هدف تقدم متطلبات'),
  FaqEntry('signoff', 'How does supervisor sign-off work?', 'On a case or procedure, add the supervisor name, role, level of supervision and date, then mark it signed after they sign on paper or verbally. No signature image is stored. Signed entries show in exports.', 'sign signoff signature supervisor consultant approve | توقيع مشرف اعتماد استشاري'),
  FaqEntry('lib', 'How do I use the library?', 'The Library tab holds medical articles that work offline. Search by title, or turn on search inside articles. Open an article to read, highlight, favourite it or save it to your reading list.', 'library article read search offline wiki | مكتبة مقال مقالات قراءة بحث'),
  FaqEntry('packs', 'How do I download library packs?', 'In the Library tab open Manage courses, pick a pack and download it (Wi-Fi is recommended). Downloaded packs work offline. You can also import your own text files, and remove packs to free space.', 'pack packs download course courses install import space storage | حزمة حزم تنزيل دورات تثبيت مساحة'),
  FaqEntry('libnotes', 'Can I make notes and cards from articles?', 'Yes. In an article add your own note, and make review cards from key points. Cards join the spaced review.', 'note highlight card cards flashcard article | ملاحظة بطاقة بطاقات مقال'),
  FaqEntry('quiz', 'How do the quizzes work?', 'In the Learn tab pick Quiz and a course or topic. Wrong answers become your weak spots and can become review cards automatically.', 'quiz test mcq questions exam practice weak | اختبار اختبارات أسئلة تدريب ضعف'),
  FaqEntry('weak', 'What are weak spots?', 'Topics you missed recently in quizzes. They are listed first in the study planner and in practice sessions.', 'weak spots missed wrong topics | ضعف أخطاء مواضيع'),
  FaqEntry('planner', 'How does the study planner work?', 'Choose your exam date and the courses you are revising. The planner spreads topics over the days, puts your weak spots first and weights your current rotation.', 'plan planner study schedule exam date revise | خطة مخطط دراسة جدول امتحان مراجعة'),
  FaqEntry('review', 'How does spaced review work?', 'Review cards come back on a schedule: cards you know return later, cards you miss return sooner. Open Review from Learn each day for a short session.', 'review spaced repetition cards flashcards due daily | مراجعة تكرار بطاقات يومي'),
  FaqEntry('replay', 'What is Replay this case?', 'It hides your answer and asks you to reason through your own case again, then compares with what you recorded. Good for practising clinical reasoning.', 'replay reasoning practice own case | إعادة عرض تفكير تدريب'),
  FaqEntry('present', 'How do I practise presenting a case?', 'In the case menu choose Practice presenting, or Share case presentation to send a short summary with the case code and no names.', 'present presentation practice summary morning meeting trainer | عرض تقديم تدريب ملخص'),
  FaqEntry('calc', 'Where are the calculators?', 'In Learn, open Calculators for clinical scores and dose helpers. They work offline. Always check results against your local protocol.', 'calculator calculators score gcs bmi dose cha2ds2 | حاسبة حاسبات مقياس جرعة'),
  FaqEntry('remind', 'How do I set reminders?', 'In Settings, Reminders: daily review, finishing draft cases and weekly goals. Allow notifications when Android asks. Reminders are local and need no internet.', 'reminder reminders notification notify daily alarm | تذكير تذكيرات إشعار يومي'),
  FaqEntry('draft', 'What is a draft case?', 'A case with status Draft. A quick case stays a draft until you finish it. Home reminds you to continue the case you left.', 'draft unfinished continue status | مسودة غير مكتملة متابعة'),
  FaqEntry('lock', 'How do I lock the app with a PIN?', 'In Settings, Privacy & security, set a PIN of 4 to 6 digits and choose when to lock. You can also hide the app in recent apps and block screenshots. If you forget the PIN you may lose access, so keep a backup.', 'lock pin password security biometric fingerprint screenshot | قفل رقم سري أمان بصمة'),
  FaqEntry('privacy', 'How do I keep patient data private?', 'Never type names, ID numbers or phone numbers. Use only the case code. Run Privacy check from the case menu: it flags numbers, phones and emails. Data stays on your phone.', 'privacy private patient identifiers name phone hipaa anonymous check | خصوصية مريض اسم هاتف مجهول'),
  FaqEntry('initials', 'Can I store patient initials?', 'Only if you turn on Store patient initials in Settings. They stay on this phone and are never included in shared text, packs or AI requests.', 'initials patient identity name | الأحرف الأولى هوية'),
  FaqEntry('backup', 'How do I back up my data?', 'In Settings, Backup & export, choose Export encrypted backup, set a password and save the file somewhere safe (Drive, email to yourself). Restore it with Import backup. If you forget the password nobody can open it.', 'backup back restore export encrypted password safe lose phone | نسخة احتياطية استعادة تصدير مشفر كلمة مرور'),
  FaqEntry('restore', 'How do I move to a new phone?', 'Export an encrypted backup on the old phone, install MedLog on the new one and use Import backup. Library packs are downloaded again or imported.', 'new phone move transfer restore import switch device | هاتف جديد نقل استعادة استيراد'),
  FaqEntry('health', 'What is Data health?', 'Settings, Data health checks every file can be read and recovers from the last good copy. Damaged files are kept in a corrupt folder, never deleted.', 'data health corrupt damaged recover repair | سلامة تالف استعادة إصلاح'),
  FaqEntry('pdf', 'How do I export a PDF?', 'In Settings or Portfolio choose Export logbook, pick the range or rotation and PDF or CSV. A single case has Export as PDF in its menu. You can add supervisor sign-off lines.', 'pdf export print csv logbook report share | تصدير طباعة تقرير سجل'),
  FaqEntry('share', 'How do I share a case?', 'Case menu: Share as text (no initials), Share case presentation, or Share to colleague (encrypted) which makes a pack your colleague imports. Always run the privacy check first.', 'share send colleague pack encrypted text whatsapp | مشاركة إرسال زميل حزمة مشفرة'),
  FaqEntry('import', 'How do I import shared cases?', 'Settings, Import backup or shared cases: choose the file and enter its password. You see a summary of new and updated cases before they are added.', 'import shared cases file open colleague | استيراد حالات مشاركة ملف'),
  FaqEntry('lang', 'How do I change the language?', 'Settings, Language: English, Arabic or follow the phone. Your own typed text and stored values stay as you wrote them.', 'language arabic english switch translate rtl | لغة عربي إنجليزي تبديل'),
  FaqEntry('terms', 'What is the Medical terms language setting?', 'In the Arabic app, medical terms stay in English by default because that is how they are written in charts. Change Medical terms language in Settings to show Arabic terms instead.', 'medical terms english arabic terminology words setting | مصطلحات طبية إنجليزي عربي'),
  FaqEntry('theme', 'How do I change the look, dark mode or text size?', 'Settings, Appearance: light, dark or pure black mode, colour palette, text size, fonts and animations.', 'theme dark mode light amoled text size font palette color animation | مظهر داكن حجم خط ألوان'),
  FaqEntry('calendar', 'How do I use the calendar and duty days?', 'Open the Calendar to see shifts and logged items by day. In a rotation, generate duty days by weekdays and edit single days.', 'calendar duty days shift schedule on call | تقويم دوام مناوبة جدول'),
  FaqEntry('analytics', 'Where are my statistics?', 'Analytics in the notebooks shows cases by specialty, most frequent diagnoses and activity over the last 16 weeks. Counts show what you saw and did, not competence by themselves.', 'statistics stats analytics chart counts frequent diagnoses activity | إحصائيات تحليلات أعداد'),
  FaqEntry('reflect', 'What are reflections, achievements and QI?', 'The notebooks hold reflections, achievements, quality improvement projects and evidence notes for your portfolio. They can count towards goals.', 'reflection reflections achievement qi quality portfolio evidence notebook | تأمل إنجازات جودة دفتر'),
  FaqEntry('pubmed', 'Can I search PubMed?', 'Yes, in the notebooks open PubMed search (needs internet). Save useful papers to your evidence notes. The rest of the app works offline.', 'pubmed papers literature evidence search internet | بحث أوراق أدلة إنترنت'),
  FaqEntry('offline', 'Does MedLog work without internet?', 'Yes. Cases, library packs you downloaded, quizzes, review, planner and exports all work offline. Only downloading packs, PubMed and the optional AI features need internet.', 'offline internet wifi connection online data | دون إنترنت اتصال'),
  FaqEntry('demo', 'How do I try the app with demo data?', 'Settings, Load demo data adds fictional records to try every screen. Demo data is never included in backups and Remove demo data deletes it.', 'demo sample data try fictional test | تجريبي بيانات وهمية'),
  FaqEntry('ai', 'How do I turn on the AI assistant?', 'AI is optional and off by default. In Settings, AI, turn it on and paste your own provider key (free tiers exist). The key stays on this phone. AI only suggests; nothing is saved until you confirm.', 'ai assistant gemini key api openai claude artificial intelligence enable | ذكاء اصطناعي مساعد مفتاح تفعيل'),
  FaqEntry('aisend', 'What is sent to the AI?', 'Help questions send only your question. Case features send a de-identified summary (no names, code, dates, hospital or images) that you preview first. A case marked Never send to AI is never sent. Every request is logged on your phone.', 'ai send privacy data leave preview never send case | ذكاء اصطناعي إرسال خصوصية معاينة'),
  FaqEntry('aicase', 'What can the AI case assistant do?', 'In the case menu choose AI assistant: discuss your case (differential for your consideration), Socratic questions, suggest fields from a note, a missing-fields check, an I-PASS handover and learning points. It never replaces your judgement.', 'ai case assistant differential socratic handover ipass suggest | مساعد حالة تشخيص تفريقي تسليم'),
  FaqEntry('ainever', 'How do I stop one case from ever going to AI?', 'In the case Info tab turn on Never send this case to AI. All AI features then skip that case.', 'never send block ai case exclude opt out | عدم إرسال حظر استثناء'),
  FaqEntry('aiapply', 'Does the AI change my case by itself?', 'No. Suggested field values appear as a list with checkboxes. Nothing is saved until you tap Apply, applied fields are marked as AI-suggested, and you can undo.', 'ai suggest apply change fields confirm undo | اقتراح تطبيق تغيير تأكيد تراجع'),
  FaqEntry('summary', 'What are the week and rotation summaries?', 'Home shows your week in numbers computed on the phone. With AI on, a short narrative can be written from those counts only (no case content). Rotation PDFs can include an AI paragraph clearly marked as AI-generated.', 'summary week rotation narrative home report ai paragraph | ملخص أسبوع دورة سرد'),
  FaqEntry('tips', 'Any tips to use MedLog every day?', 'Log a quick case right after seeing the patient, write one pearl a day, do a short review session, and back up once a week. Use the case code, never names.', 'tips habit daily workflow best practice advice start | نصائح عادة يومي بداية'),
  FaqEntry('code', 'What is the case code?', 'Each case gets a code such as IM-0001. Use it to recognise a patient instead of a name. It is shown in shared presentations but never sent to AI.', 'code id number identify patient case code | رمز حالة تعريف'),
  FaqEntry('similar', 'Can I find similar or related cases?', 'Case menu: Similar & related lists your other cases with the same diagnosis or tags, and Compare with another case shows them side by side.', 'similar related compare cases same diagnosis | مشابهة مقارنة حالات'),
  FaqEntry('libcase', 'Can I read about my case diagnosis in the library?', 'Case menu: Read about this in the library finds matching articles from your downloaded packs.', 'read library diagnosis article about case | قراءة مكتبة تشخيص مقال'),
  FaqEntry('sync', 'Is my data synced to the cloud?', 'No. Everything is stored on this phone only. That is why regular encrypted backups matter.', 'cloud sync account server stored online store | سحابة مزامنة حساب خادم'),
  FaqEntry('sheet', 'Where is the cheat sheet or glance view?', 'Many library articles have a quick sheet view with the key points. Turn it on in the article menu or in Library settings.', 'sheet glance summary cheat key points quick article | ملخص سريع نقاط'),
  FaqEntry('dictionary', 'Is there a medical dictionary?', 'Yes, the Library has a Dictionary for medical terms that works offline, including Arabic equivalents.', 'dictionary terms meaning translate arabic word | قاموس مصطلحات معنى ترجمة'),
  FaqEntry('aiask', 'What is the Ask AI button?', 'When AI is on, a floating Ask AI button appears on the main screens. It knows which screen you are on (case, calculator, quiz, library, home, search) and offers the right actions. Drag it where you like; switch it off, or per screen, in Settings, AI assistant.', 'ask ai floating button fab chat assistant drag move hide screen | زر اسأل الذكاء الاصطناعي عائم دردشة مساعد سحب إخفاء'),
  FaqEntry('aisources', 'What sources does the AI use?', 'In Settings, AI assistant, choose the sources: trusted web (live search limited to guideline sites that you can edit), your own library, the model only, or your own list of sites. Web answers name the organisation, the year and the link. When no source is found the answer says so.', 'sources web library guideline citation trusted sites domains custom live search reference | مصادر ويب مكتبة إرشادات استشهاد مواقع موثوقة بحث'),
  FaqEntry('ailang', 'Which language does the AI answer in?', 'English by default. In Settings, AI assistant you can choose an Arabic explanation with English medical terms, or Arabic. Clinical terms, drug names and guideline names stay in English.', 'language english arabic answer mixed terms translate ai | لغة الإجابة عربي إنجليزي مصطلحات ذكاء اصطناعي'),
  FaqEntry('aiformat', 'How are AI answers formatted?', 'Answers come as a structured sheet with sections (overview, differential, investigations, management, red flags, guidelines) and source chips; tap a chip to open the source. You can switch to plain text, hide citations, copy the answer or report a problem.', 'format formatting sheet cards sections table citations copy plain text answer layout | تنسيق ورقة أقسام جدول استشهادات نسخ نص'),
  FaqEntry('aibank', 'What is the AI question bank?', 'Home, AI question bank keeps practice questions made from your library or from cited answers. Saved questions work offline. From a case, the Teach tab saves cited questions and review cards.', 'ai question bank practice questions quiz saved mcq cited teach | بنك أسئلة الذكاء الاصطناعي أسئلة تدريب محفوظة'),
  FaqEntry('aiviva', 'Can the AI test me like a viva or OSCE?', 'Yes. In Ask AI choose viva practice: the AI asks one question at a time and gives feedback. In a case, Socratic mode does the same with your own case.', 'viva osce exam practice examiner oral socratic questions test me | فيفا أوسكي امتحان شفهي ممتحن أسئلة سقراطي'),
  FaqEntry('aiguide', 'How do I check a topic against the current guidelines?', 'In Ask AI use the guideline check action, or open the Guidelines tab of a case: you get a table of organisation, year and recommendation for the working diagnosis. It never gives orders for your patient.', 'guideline check current latest what changed recommendation table nice who case | إرشادات فحص حديثة توصية جدول تشخيص'),
  FaqEntry('aivoice', 'Can I dictate notes by voice?', 'Yes. The microphone button next to a note or answer field uses the speech recogniser of your phone. In the case assistant, the Fields tab turns a dictated or pasted note into suggested fields that you apply or undo.', 'voice dictate microphone speech note mic talk fields | صوت إملاء ميكروفون كلام ملاحظة حقول'),
  FaqEntry('aidrug', 'How does Drug check work?', 'Calculators, Drug check answers questions on interactions, kidney or liver dose, pregnancy and children only when it finds a cited source on the allowed sites or in your library packs. Otherwise it says No verified source found. Always verify in your hospital formulary.', 'drug check interaction dose renal hepatic pregnancy children paediatric formulary medication source | فحص دواء تداخل جرعة كلوي كبدي حمل أطفال مصدر'),
  FaqEntry('aiscore', 'How do I find the right score for a case?', 'Calculators, Which score fits this case? suggests scores with their sources. The app does all the arithmetic, and Interpret my result explains your number with guideline thresholds.', 'score calculator which fits interpret result wells curb gcs threshold case | درجة حاسبة أي مقياس تفسير نتيجة'),
  FaqEntry('aibrief', 'What is the morning brief?', 'On Home it lists today cases, due flashcards, goals, rotation and weak topics, all computed on your phone. With AI on it can write a short paragraph from those counts only.', 'morning brief home today summary due flashcards goals weak topics | ملخص صباحي الرئيسية اليوم بطاقات أهداف'),
  FaqEntry('aiportfolio', 'What can AI do in my portfolio?', 'Portfolio, AI portfolio tools: a reflection draft from one of your cases (marked DRAFT), a goal gap analysis with next actions, and a CV summary from your counts. Reports can add a marked AI paragraph.', 'portfolio reflection draft goal gap cv summary report narrative rotation ai | ملف تأمل مسودة فجوة أهداف سيرة ذاتية تقرير'),
  FaqEntry('aisettings', 'Where are the AI settings?', 'Settings, AI assistant: provider and key, allowed sites, answer language and length, formatting, the floating button, which features are on, the daily limit and the activity log.', 'ai settings provider key limit log features switches | إعدادات الذكاء الاصطناعي مزود مفتاح مصادر لغة'),
  FaqEntry('aigate', 'What is the access approval?', 'If your administrator turned on access control, the app shows a request code that you send to the administrator, who returns an approval code. Settings, Access shows the status and the days left. It is checked offline and no patient data is involved.', 'access approval gate administrator code request member expiry | موافقة وصول مسؤول رمز طلب عضو انتهاء'),
  FaqEntry('aioff', 'What if I do not use AI?', 'Everything in MedLog works without it. Each AI action stays visible but greyed with a Turn on AI link, and nothing is sent anywhere until you turn AI on and confirm.', 'ai off disabled without turn on optional greyed offline internet | بدون ذكاء اصطناعي تعطيل تشغيل اختياري'),
  FaqEntry('cards', 'How do I use Presentation cards?', "In the Library tab open Presentation cards, search a symptom such as chest pain, and read what to ask, what to examine, the red flags, the can't-miss diagnoses and the first steps. They hold no drug doses. Check your hospital protocol.", "cards presentation symptom red flags chest pain bedside checklist can't miss | بطاقات عرض عرض مرضي علامات حمراء ألم صدر"),
  FaqEntry('rothub', 'What is the Rotation hub?', 'In the Library tab open Rotation hub, pick a specialty and see its core topics (tick them as you study), common presentations, red flags, procedures and suggested case numbers. The search button next to a topic looks it up in your library.', 'rotation hub specialty topics curriculum targets study progress | مركز التدوير تخصص مواضيع منهج أهداف'),
  FaqEntry('scores', 'Which clinical scores are in Calculators?', 'Calculators now include many more scores, for example SOFA, qSOFA, HEART, TIMI, NIHSS, ABCD2, Alvarado, Child-Pugh, MELD, PHQ-9, GAD-7, Apgar, Padua, HAS-BLED, Glasgow-Blatchford, Bishop, Ottawa rules and the Canadian CT head rule. Answer every question to see the result. Each score shows its source and limits.', 'score scores calculator sofa heart nihss meld phq gad apgar padua bishop ottawa | مقياس مقاييس حاسبة'),
  FaqEntry('samepatient', 'How do I follow one patient over time?', 'In the Info tab of a case open Same patient and outcome. Link another case of the same patient or add a follow-up case. No name or number is stored: the cases only share a hidden group. Set the outcome of the case there too.', 'same patient link follow up followup outcome longitudinal | مريض نفسه ربط متابعة نتيجة'),
  FaqEntry('labs', 'How do I track lab results and problems?', 'In the Investigations tab add numeric results (for example Hb or creatinine) on different days to see the trend. In the Assessment tab use the Problem list and tick problems when resolved. You can import the lines you already wrote.', 'lab labs results trend problem list problems hb creatinine | مختبر نتائج اتجاه قائمة مشاكل'),
  FaqEntry('errlog', 'What is the error log?', 'Settings, Data & recovery, Error log keeps the last unexpected errors on this phone only. Copy it when you report a problem. Nothing is sent anywhere.', 'error errors log crash bug report problem | خطأ أخطاء سجل مشكلة إبلاغ'),
  FaqEntry('aiquality', 'What is the AI quality check?', 'In AI settings, AI quality check sends fixed medical test questions with no patient data to your own AI key and reports how many answers contained the key facts and avoided unsafe statements. Use it to compare models. It is a keyword check, not a clinical judgement.', 'ai quality check test model compare accuracy safety | جودة فحص ذكاء نموذج مقارنة'),
];
